INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-led-channel-letters','product','led-channel-letters','{"title":"LED Channel Letters","intro":"Give your business name or logo an illuminated presence. Share the look you want, and we’ll review the letter construction, face material and lighting requirements for your project.","body":"## A Defined, Illuminated Letter Face\n\nUse this direction when the face of your lettering needs to read clearly as part of a shopfront, reception or commercial identity. The face, return, depth and lighting layout work together; a photograph alone does not define the construction.\n\nThe supplier images below show a letter face and internal lighting reference. They do not establish the final brightness, electrical specification or outdoor suitability of your order.\n\n## What We Can Review with You\n\n- Logo or lettering: vector artwork is useful, but a reference image can start the discussion.\n- Overall dimensions, individual letter size and quantity.\n- Face colour and appearance with the lighting switched on and off.\n- Side finish, letter depth and visible edges.\n- Mounting surface, access for wiring and any carrier or fixing arrangement.\n- Destination-specific electrical and documentation requirements.\n\n## Show Us the Installation Location\n\nSend a straight-on photo of the wall or fascia and any approximate measurements you have. Tell us whether it is indoors, sheltered or exposed. We review the proposed assembly and available documents before confirming suitability; this page makes no blanket weather or certification claim.\n\n## What Goes into the Quote?\n\nArtwork complexity, size, material, finish, lighting, quantity, mounting and delivery scope all affect the proposal. Ask us to identify included components, exclusions and any assumptions while dimensions are still provisional.\n\n## Questions Before You Start\n\n### Can I begin without a production drawing?\n\nYes. Share your logo, intended location and approximate size. Final artwork and dimensions need approval before fabrication is authorised.\n\n### Will the sign look the same during the day and at night?\n\nThe appearance can change with face material, light colour and ambient lighting. Tell us which viewing conditions matter so these can be reviewed with the specification.\n\n### Is local installation included?\n\nDo not assume it is. Fixings, wiring, electrical connection, access and local installation responsibilities must be agreed in the project scope.","image":"/assets/frontlit-form.webp","imageAlt":"LED Channel Letters illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":0,"seedIndex":0,"gallery":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Unlit letter face and metal return from the supplier brochure","caption":"Supplier reference — unlit face and return reference."},{"src":"/assets/supplier/led-layout-reference.webp","alt":"LED modules visible inside a letter in the supplier brochure","caption":"Supplier reference — illustrative module arrangement, not a specified electrical assembly."}]}','{"title":"LED Channel Letters","intro":"Give your business name or logo an illuminated presence. Share the look you want, and we’ll review the letter construction, face material and lighting requirements for your project.","body":"## A Defined, Illuminated Letter Face\n\nUse this direction when the face of your lettering needs to read clearly as part of a shopfront, reception or commercial identity. The face, return, depth and lighting layout work together; a photograph alone does not define the construction.\n\nThe supplier images below show a letter face and internal lighting reference. They do not establish the final brightness, electrical specification or outdoor suitability of your order.\n\n## What We Can Review with You\n\n- Logo or lettering: vector artwork is useful, but a reference image can start the discussion.\n- Overall dimensions, individual letter size and quantity.\n- Face colour and appearance with the lighting switched on and off.\n- Side finish, letter depth and visible edges.\n- Mounting surface, access for wiring and any carrier or fixing arrangement.\n- Destination-specific electrical and documentation requirements.\n\n## Show Us the Installation Location\n\nSend a straight-on photo of the wall or fascia and any approximate measurements you have. Tell us whether it is indoors, sheltered or exposed. We review the proposed assembly and available documents before confirming suitability; this page makes no blanket weather or certification claim.\n\n## What Goes into the Quote?\n\nArtwork complexity, size, material, finish, lighting, quantity, mounting and delivery scope all affect the proposal. Ask us to identify included components, exclusions and any assumptions while dimensions are still provisional.\n\n## Questions Before You Start\n\n### Can I begin without a production drawing?\n\nYes. Share your logo, intended location and approximate size. Final artwork and dimensions need approval before fabrication is authorised.\n\n### Will the sign look the same during the day and at night?\n\nThe appearance can change with face material, light colour and ambient lighting. Tell us which viewing conditions matter so these can be reviewed with the specification.\n\n### Is local installation included?\n\nDo not assume it is. Fixings, wiring, electrical connection, access and local installation responsibilities must be agreed in the project scope.","image":"/assets/frontlit-form.webp","imageAlt":"LED Channel Letters illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":0,"seedIndex":0,"gallery":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Unlit letter face and metal return from the supplier brochure","caption":"Supplier reference — unlit face and return reference."},{"src":"/assets/supplier/led-layout-reference.webp","alt":"LED modules visible inside a letter in the supplier brochure","caption":"Supplier reference — illustrative module arrangement, not a specified electrical assembly."}]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-backlit-letters','product','backlit-letters','{"title":"Backlit & Halo Lit Letters","intro":"Create a glow behind your logo or lettering. Explore backlit sign examples, then discuss the finish, lighting and mounting arrangement for your space.","body":"## A Glow Around Your Lettering\n\nBacklit or halo-lit lettering creates light behind the letter rather than treating the front face as the main illuminated surface. It can give a logo or name a distinct outline on a reception wall or commercial facade.\n\nThe visible glow depends on the letter, distance from the wall, wall colour and texture, surrounding light and viewing angle. A reference photograph is a design direction, not a promise of an identical halo in a different space.\n\n## Define the Face and the Glow Together\n\n- Lettering or logo shape, overall dimensions and quantity.\n- Visible face finish and side appearance.\n- Preferred light colour and the effect you want behind the letters.\n- Proposed mounting surface, spacing and visible fixing details.\n- Cable routing, access and power arrangement to be reviewed.\n- Indoor or outdoor location and destination requirements.\n\n## Bring the Wall into the Conversation\n\nA close photo of the wall and a wider photo of the space help us understand the setting. Dark, glossy, textured or uneven surfaces can change how a halo appears. Discuss constraints before choosing a finish or approving the final arrangement.\n\n## Confirm Before Production\n\nThe quotation and approved artwork should identify the construction, dimensions, finish, lighting and mounting scope. Any required sample, lighting review or support documentation must be agreed separately, along with delivery and local installation responsibilities.\n\n## Questions Before You Start\n\n### Can the face have a metal finish?\n\nShare the finish or colour reference you want. Available materials, coatings and the final appearance need review for the specific design.\n\n### Can a small or intricate logo be backlit?\n\nFine strokes and small spaces can affect construction and lighting options. Send the artwork and intended size so we can review what is practical.\n\n### Are the pictured mounting details included?\n\nThey are supplier references. Your mounting method, supplied parts and site work are defined in your own approved project scope.","image":"/assets/office-halo.webp","imageAlt":"Backlit & Halo Lit Letters illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":1,"seedIndex":1,"gallery":[{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Individual illuminated letters from the supplier brochure","caption":"Supplier reference — individual letter samples with rear illumination."},{"src":"/assets/supplier/letter-edge-section.webp","alt":"Close view of a metal letter edge in the supplier brochure","caption":"Supplier reference — letter edge and return detail; construction is agreed per project."}]}','{"title":"Backlit & Halo Lit Letters","intro":"Create a glow behind your logo or lettering. Explore backlit sign examples, then discuss the finish, lighting and mounting arrangement for your space.","body":"## A Glow Around Your Lettering\n\nBacklit or halo-lit lettering creates light behind the letter rather than treating the front face as the main illuminated surface. It can give a logo or name a distinct outline on a reception wall or commercial facade.\n\nThe visible glow depends on the letter, distance from the wall, wall colour and texture, surrounding light and viewing angle. A reference photograph is a design direction, not a promise of an identical halo in a different space.\n\n## Define the Face and the Glow Together\n\n- Lettering or logo shape, overall dimensions and quantity.\n- Visible face finish and side appearance.\n- Preferred light colour and the effect you want behind the letters.\n- Proposed mounting surface, spacing and visible fixing details.\n- Cable routing, access and power arrangement to be reviewed.\n- Indoor or outdoor location and destination requirements.\n\n## Bring the Wall into the Conversation\n\nA close photo of the wall and a wider photo of the space help us understand the setting. Dark, glossy, textured or uneven surfaces can change how a halo appears. Discuss constraints before choosing a finish or approving the final arrangement.\n\n## Confirm Before Production\n\nThe quotation and approved artwork should identify the construction, dimensions, finish, lighting and mounting scope. Any required sample, lighting review or support documentation must be agreed separately, along with delivery and local installation responsibilities.\n\n## Questions Before You Start\n\n### Can the face have a metal finish?\n\nShare the finish or colour reference you want. Available materials, coatings and the final appearance need review for the specific design.\n\n### Can a small or intricate logo be backlit?\n\nFine strokes and small spaces can affect construction and lighting options. Send the artwork and intended size so we can review what is practical.\n\n### Are the pictured mounting details included?\n\nThey are supplier references. Your mounting method, supplied parts and site work are defined in your own approved project scope.","image":"/assets/office-halo.webp","imageAlt":"Backlit & Halo Lit Letters illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":1,"seedIndex":1,"gallery":[{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Individual illuminated letters from the supplier brochure","caption":"Supplier reference — individual letter samples with rear illumination."},{"src":"/assets/supplier/letter-edge-section.webp","alt":"Close view of a metal letter edge in the supplier brochure","caption":"Supplier reference — letter edge and return detail; construction is agreed per project."}]}','published',1);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-metal-letters','product','metal-letters','{"title":"Metal & Dimensional Letters","intro":"Give your logo depth through raised lettering and considered surface details. Explore metal lettering examples and discuss the finish and construction that suit your project.","body":"## Lettering with Depth and a Visible Finish\n\nMetal and dimensional lettering can emphasise a logo through its outline, thickness, edge profile and surface finish. Start by comparing the appearance you want rather than assuming all metallic-looking signs use the same material or process.\n\nThe supplier photographs show formed letters and close surface details. Their colour on your screen does not establish a finish match, material grade or exterior durability.\n\n## Shape, Finish and Fixing Options to Review\n\n- Logo outline, lettering style, size, depth and quantity.\n- Flat-cut or built-up appearance, subject to design review.\n- Brushed, polished, coated or other requested surface direction.\n- Edge treatment, visible sides and any mounting stand-off.\n- Mounting surface and whether the sign will be illuminated.\n- Location, cleaning conditions and destination requirements.\n\n## Illuminated or Non-illuminated?\n\nA metal face does not by itself describe the lighting arrangement. Tell us whether you want an unlit dimensional sign, a halo behind the letters or another effect. The construction and electrical scope need confirmation for the selected version.\n\n## Discuss the Surface Reference\n\nSend a colour reference, material sample or clear photograph if the finish is important. Ask which sample or approval method is available before production. Do not rely on a screen image to confirm an exact metallic colour.\n\n## Questions Before You Start\n\n### Can you review my existing logo?\n\nYes. Include the artwork, intended size and a photo of the location. We will identify details that need clarification before quoting.\n\n### Which material should I choose outdoors?\n\nThe answer depends on the actual alloy or substrate, finish, environment and fixing arrangement. State the conditions and any required evidence at the enquiry stage; no universal outdoor specification is claimed here.\n\n### How do I prepare for installation?\n\nConfirm the supplied fixing parts, layout information, mounting surface and local installer''s responsibilities. Any drilling, access equipment or electrical work must be agreed separately.","image":"/assets/metal-studio-portrait.webp","imageAlt":"Metal & Dimensional Letters illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":2,"seedIndex":2,"gallery":[{"src":"/assets/supplier/formed-metal-letters.webp","alt":"Raised metal letters spelling USA in a supplier reference","caption":"Supplier reference — formed lettering and visible side depth; no project location is claimed."},{"src":"/assets/supplier/letter-edge-section.webp","alt":"Close view of a metal letter edge in the supplier brochure","caption":"Supplier reference — letter edge and return detail; construction is agreed per project."},{"src":"/assets/supplier/letter-return-detail.webp","alt":"Close view of a curved metal letter return","caption":"Supplier reference — curved return and surface detail."}]}','{"title":"Metal & Dimensional Letters","intro":"Give your logo depth through raised lettering and considered surface details. Explore metal lettering examples and discuss the finish and construction that suit your project.","body":"## Lettering with Depth and a Visible Finish\n\nMetal and dimensional lettering can emphasise a logo through its outline, thickness, edge profile and surface finish. Start by comparing the appearance you want rather than assuming all metallic-looking signs use the same material or process.\n\nThe supplier photographs show formed letters and close surface details. Their colour on your screen does not establish a finish match, material grade or exterior durability.\n\n## Shape, Finish and Fixing Options to Review\n\n- Logo outline, lettering style, size, depth and quantity.\n- Flat-cut or built-up appearance, subject to design review.\n- Brushed, polished, coated or other requested surface direction.\n- Edge treatment, visible sides and any mounting stand-off.\n- Mounting surface and whether the sign will be illuminated.\n- Location, cleaning conditions and destination requirements.\n\n## Illuminated or Non-illuminated?\n\nA metal face does not by itself describe the lighting arrangement. Tell us whether you want an unlit dimensional sign, a halo behind the letters or another effect. The construction and electrical scope need confirmation for the selected version.\n\n## Discuss the Surface Reference\n\nSend a colour reference, material sample or clear photograph if the finish is important. Ask which sample or approval method is available before production. Do not rely on a screen image to confirm an exact metallic colour.\n\n## Questions Before You Start\n\n### Can you review my existing logo?\n\nYes. Include the artwork, intended size and a photo of the location. We will identify details that need clarification before quoting.\n\n### Which material should I choose outdoors?\n\nThe answer depends on the actual alloy or substrate, finish, environment and fixing arrangement. State the conditions and any required evidence at the enquiry stage; no universal outdoor specification is claimed here.\n\n### How do I prepare for installation?\n\nConfirm the supplied fixing parts, layout information, mounting surface and local installer''s responsibilities. Any drilling, access equipment or electrical work must be agreed separately.","image":"/assets/metal-studio-portrait.webp","imageAlt":"Metal & Dimensional Letters illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":2,"seedIndex":2,"gallery":[{"src":"/assets/supplier/formed-metal-letters.webp","alt":"Raised metal letters spelling USA in a supplier reference","caption":"Supplier reference — formed lettering and visible side depth; no project location is claimed."},{"src":"/assets/supplier/letter-edge-section.webp","alt":"Close view of a metal letter edge in the supplier brochure","caption":"Supplier reference — letter edge and return detail; construction is agreed per project."},{"src":"/assets/supplier/letter-return-detail.webp","alt":"Close view of a curved metal letter return","caption":"Supplier reference — curved return and surface detail."}]}','published',2);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-acrylic-letters','product','acrylic-letters','{"title":"Acrylic Letters & Signs","intro":"Explore acrylic lettering, logo shapes and layered sign designs. Share the colour, depth and overall appearance you have in mind.","body":"## Colour, Edges and Layered Shapes\n\nAcrylic lettering and signs can use cut shapes, visible edges and separate layers to create a dimensional logo. Use a reference to explain the effect you want, then review the material, colour, thickness and construction for your own artwork.\n\nThe supplier image shows a coloured letter with a clear lower layer. It is a construction reference, not a fixed specification that every acrylic sign must follow.\n\n## Start with These Design Choices\n\n- Logo or lettering, overall width and height, and quantity.\n- Desired colour, opacity and appearance of the edges.\n- Single or multiple layers and the depth you want to see.\n- Background, backing panel or individual letters.\n- Preferred illuminated or non-illuminated effect.\n- Mounting surface, indoor or outdoor setting and destination.\n\n## Artwork and Small Details\n\nFine strokes, tight spaces and separate logo elements need review at the intended size. If you only have a screenshot, send it to begin the discussion; production artwork and final dimensions must be confirmed before fabrication.\n\n## Review the Fixing and Handling Scope\n\nThe sign''s size, layers and mounting surface affect how it should be supported and handled. Confirm the supplied fixing arrangement, layout information, packing and local installation requirements in the quotation.\n\n## Questions Before You Start\n\n### Are acrylic signs always illuminated?\n\nNo. Acrylic can be used in unlit signs or as part of an illuminated assembly. Tell us the appearance you want rather than assuming the image includes lighting.\n\n### Can you match a brand colour?\n\nShare your colour reference and ask how the selected material or finish will be approved. Availability, lighting and viewing conditions can affect the perceived colour.\n\n### Can I send an approximate size?\n\nYes, for an initial discussion. Confirm the final measurements, artwork, layer arrangement and installation surface before production is approved.","image":"/assets/acrylic-sign.webp","imageAlt":"Acrylic Letters & Signs illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":3,"seedIndex":3,"gallery":[{"src":"/assets/supplier/layered-acrylic-letter.webp","alt":"Blue letter with clear layers from the supplier brochure","caption":"Supplier reference — coloured face and clear layered construction reference."}]}','{"title":"Acrylic Letters & Signs","intro":"Explore acrylic lettering, logo shapes and layered sign designs. Share the colour, depth and overall appearance you have in mind.","body":"## Colour, Edges and Layered Shapes\n\nAcrylic lettering and signs can use cut shapes, visible edges and separate layers to create a dimensional logo. Use a reference to explain the effect you want, then review the material, colour, thickness and construction for your own artwork.\n\nThe supplier image shows a coloured letter with a clear lower layer. It is a construction reference, not a fixed specification that every acrylic sign must follow.\n\n## Start with These Design Choices\n\n- Logo or lettering, overall width and height, and quantity.\n- Desired colour, opacity and appearance of the edges.\n- Single or multiple layers and the depth you want to see.\n- Background, backing panel or individual letters.\n- Preferred illuminated or non-illuminated effect.\n- Mounting surface, indoor or outdoor setting and destination.\n\n## Artwork and Small Details\n\nFine strokes, tight spaces and separate logo elements need review at the intended size. If you only have a screenshot, send it to begin the discussion; production artwork and final dimensions must be confirmed before fabrication.\n\n## Review the Fixing and Handling Scope\n\nThe sign''s size, layers and mounting surface affect how it should be supported and handled. Confirm the supplied fixing arrangement, layout information, packing and local installation requirements in the quotation.\n\n## Questions Before You Start\n\n### Are acrylic signs always illuminated?\n\nNo. Acrylic can be used in unlit signs or as part of an illuminated assembly. Tell us the appearance you want rather than assuming the image includes lighting.\n\n### Can you match a brand colour?\n\nShare your colour reference and ask how the selected material or finish will be approved. Availability, lighting and viewing conditions can affect the perceived colour.\n\n### Can I send an approximate size?\n\nYes, for an initial discussion. Confirm the final measurements, artwork, layer arrangement and installation surface before production is approved.","image":"/assets/acrylic-sign.webp","imageAlt":"Acrylic Letters & Signs illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":3,"seedIndex":3,"gallery":[{"src":"/assets/supplier/layered-acrylic-letter.webp","alt":"Blue letter with clear layers from the supplier brochure","caption":"Supplier reference — coloured face and clear layered construction reference."}]}','published',3);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-lightbox-neon','product','lightbox-neon','{"title":"Lightboxes & Neon-style Signs","intro":"Explore illuminated sign faces and line-based lighting effects. Choose the direction you like, then discuss the construction and details for your project.","body":"## Two Different Lighting Directions\n\nLightboxes and neon-style signs are grouped here as starting points for an enquiry, but they use different visual and construction approaches. Tell us which reference you prefer so the quote can identify the actual assembly.\n\n## Lightbox Signs\n\nA lightbox uses an illuminated face or panel within an enclosure. Discuss the overall shape, artwork, face appearance, depth, mounting location and how the sign will be accessed for installation or maintenance. The enclosure, light source and supplied electrical parts need project-specific confirmation.\n\n## Neon-style Signs\n\nThis direction uses illuminated lines, letters or graphic shapes. The supplier reference shows examples of the visual effect. The term “neon-style” does not identify whether a proposed product uses glass neon, LED neon flex or another construction; the actual light source must be specified before ordering.\n\n## Information That Helps Us Review Your Idea\n\n- Logo, lettering or line drawing, including any small details.\n- Approximate overall dimensions and quantity.\n- Colours and the appearance you want when illuminated.\n- Indoor or outdoor use, wall or hanging position, and access to power.\n- Backing, enclosure and visible fixing preferences.\n- Destination and any required documentation.\n\n## Questions Before You Start\n\n### Can every logo be made as illuminated lines?\n\nNot necessarily in the same form or size. Fine details, line spacing and tight corners need review; we will discuss any proposed changes before approval.\n\n### Can I request a different colour or shape?\n\nShare the reference. Available colours, construction and any controls must be checked for the selected product and included in the quote if agreed.\n\n### What should I confirm about power and installation?\n\nIdentify the destination market, intended location and local installer''s requirements. Agree supplied components, connection responsibilities and supporting documents before production.","image":"/assets/lightbox-sign.webp","imageAlt":"Lightboxes & Neon-style Signs illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":4,"seedIndex":4,"gallery":[{"src":"/assets/supplier/neon-style-signs.webp","alt":"Illuminated cup and dessert line graphics in the supplier brochure","caption":"Supplier reference — neon-style visual examples; actual light source to be confirmed."}]}','{"title":"Lightboxes & Neon-style Signs","intro":"Explore illuminated sign faces and line-based lighting effects. Choose the direction you like, then discuss the construction and details for your project.","body":"## Two Different Lighting Directions\n\nLightboxes and neon-style signs are grouped here as starting points for an enquiry, but they use different visual and construction approaches. Tell us which reference you prefer so the quote can identify the actual assembly.\n\n## Lightbox Signs\n\nA lightbox uses an illuminated face or panel within an enclosure. Discuss the overall shape, artwork, face appearance, depth, mounting location and how the sign will be accessed for installation or maintenance. The enclosure, light source and supplied electrical parts need project-specific confirmation.\n\n## Neon-style Signs\n\nThis direction uses illuminated lines, letters or graphic shapes. The supplier reference shows examples of the visual effect. The term “neon-style” does not identify whether a proposed product uses glass neon, LED neon flex or another construction; the actual light source must be specified before ordering.\n\n## Information That Helps Us Review Your Idea\n\n- Logo, lettering or line drawing, including any small details.\n- Approximate overall dimensions and quantity.\n- Colours and the appearance you want when illuminated.\n- Indoor or outdoor use, wall or hanging position, and access to power.\n- Backing, enclosure and visible fixing preferences.\n- Destination and any required documentation.\n\n## Questions Before You Start\n\n### Can every logo be made as illuminated lines?\n\nNot necessarily in the same form or size. Fine details, line spacing and tight corners need review; we will discuss any proposed changes before approval.\n\n### Can I request a different colour or shape?\n\nShare the reference. Available colours, construction and any controls must be checked for the selected product and included in the quote if agreed.\n\n### What should I confirm about power and installation?\n\nIdentify the destination market, intended location and local installer''s requirements. Agree supplied components, connection responsibilities and supporting documents before production.","image":"/assets/lightbox-sign.webp","imageAlt":"Lightboxes & Neon-style Signs illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":4,"seedIndex":4,"gallery":[{"src":"/assets/supplier/neon-style-signs.webp","alt":"Illuminated cup and dessert line graphics in the supplier brochure","caption":"Supplier reference — neon-style visual examples; actual light source to be confirmed."}]}','published',4);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-specialty-signs','product','specialty-signs','{"title":"Specialty Custom Signs","intro":"Have a sign idea that goes beyond a standard look? Share the effect, finish or construction you are trying to achieve.","body":"## Begin with the Effect You Want to Achieve\n\nSome sign ideas are better explained with a sketch or reference than with a product name. This page is for exposed-light lettering, distinctive surfaces and other fabrication directions that need an individual construction review.\n\nThe supplier reference shows a letter with visible points of light. It does not mean every shape, size, lighting effect or finish can be reproduced without changes.\n\n## Describe the Important Parts of the Reference\n\n- Which elements matter: outline, depth, surface, visible light points or overall character.\n- Your own logo or lettering and approximate dimensions.\n- Preferred colours, finish and illuminated or unlit appearance.\n- Quantity, intended location and mounting surface.\n- Delivery country and any timing or documentation constraints.\n\n## Review Feasibility Before Approving a Specification\n\nA photograph may hide the light source, supports, wiring and material build-up. We review these points with the manufacturing partner and identify what needs a drawing, sample or further confirmation. Any proposed alternative should be agreed rather than silently treated as an exact match.\n\n## Scope the Quote Clearly\n\nConfirm the artwork, materials, finish, lighting, mounting, supplied components, packing and delivery arrangements. Ask which assumptions remain if you request an initial estimate before the technical details are final.\n\n## Questions Before You Start\n\n### Can you reproduce a sign from a photograph?\n\nUse it to describe a visual direction. We cannot confirm an exact construction or match from a photograph alone. Send your own artwork and identify the details that matter.\n\n### What if I do not know the process name?\n\nThat is fine. Describe the appearance and intended use in ordinary language. We can clarify the fabrication questions during the enquiry.\n\n### Can a special lighting effect be used outdoors?\n\nOnly after the proposed assembly and conditions have been reviewed. Required electrical, environmental and local installation evidence must be agreed for the actual project.","image":"/assets/specialty-sign.webp","imageAlt":"Specialty Custom Signs illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":5,"seedIndex":5,"gallery":[{"src":"/assets/supplier/exposed-light-letter.webp","alt":"Letter with exposed light points from the supplier brochure","caption":"Supplier reference — exposed-light lettering reference."}]}','{"title":"Specialty Custom Signs","intro":"Have a sign idea that goes beyond a standard look? Share the effect, finish or construction you are trying to achieve.","body":"## Begin with the Effect You Want to Achieve\n\nSome sign ideas are better explained with a sketch or reference than with a product name. This page is for exposed-light lettering, distinctive surfaces and other fabrication directions that need an individual construction review.\n\nThe supplier reference shows a letter with visible points of light. It does not mean every shape, size, lighting effect or finish can be reproduced without changes.\n\n## Describe the Important Parts of the Reference\n\n- Which elements matter: outline, depth, surface, visible light points or overall character.\n- Your own logo or lettering and approximate dimensions.\n- Preferred colours, finish and illuminated or unlit appearance.\n- Quantity, intended location and mounting surface.\n- Delivery country and any timing or documentation constraints.\n\n## Review Feasibility Before Approving a Specification\n\nA photograph may hide the light source, supports, wiring and material build-up. We review these points with the manufacturing partner and identify what needs a drawing, sample or further confirmation. Any proposed alternative should be agreed rather than silently treated as an exact match.\n\n## Scope the Quote Clearly\n\nConfirm the artwork, materials, finish, lighting, mounting, supplied components, packing and delivery arrangements. Ask which assumptions remain if you request an initial estimate before the technical details are final.\n\n## Questions Before You Start\n\n### Can you reproduce a sign from a photograph?\n\nUse it to describe a visual direction. We cannot confirm an exact construction or match from a photograph alone. Send your own artwork and identify the details that matter.\n\n### What if I do not know the process name?\n\nThat is fine. Describe the appearance and intended use in ordinary language. We can clarify the fabrication questions during the enquiry.\n\n### Can a special lighting effect be used outdoors?\n\nOnly after the proposed assembly and conditions have been reviewed. Required electrical, environmental and local installation evidence must be agreed for the actual project.","image":"/assets/specialty-sign.webp","imageAlt":"Specialty Custom Signs illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept from approved UI","indexable":true,"sort":5,"seedIndex":5,"gallery":[{"src":"/assets/supplier/exposed-light-letter.webp","alt":"Letter with exposed light points from the supplier brochure","caption":"Supplier reference — exposed-light lettering reference."}]}','published',5);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('project-office-logo-concept','project','office-logo-concept','{"title":"Office Logo Sign","intro":"Backlit lettering in a reception setting.","body":"## The Design Brief\n\nThis illustrative concept explores a backlit logo as a focal point behind a reception desk. It is a visual starting point, not a completed client installation or a supplied construction drawing.\n\n## What to Review for Your Space\n\nCompare the logo scale with the reception wall, the visible face finish and the halo behind the letters. Wall colour, texture, mounting distance and room lighting can change the result. Send a wider photograph and approximate wall measurements with your artwork.\n\n## Turn the Direction into Your Own Specification\n\nReview overall dimensions, individual shapes, face and side finish, light colour, fixing method, cable route and access. Any required documents and the local installer''s responsibilities must be agreed before the design is approved for production.","image":"/assets/office-halo.webp","imageAlt":"Office Logo Sign illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept","product":"backlit-letters","setting":"Office","indexable":false,"sort":0,"gallery":[{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Individual illuminated letters from the supplier brochure","caption":"Supplier reference — individual letter samples with rear illumination."}]}','{"title":"Office Logo Sign","intro":"Backlit lettering in a reception setting.","body":"## The Design Brief\n\nThis illustrative concept explores a backlit logo as a focal point behind a reception desk. It is a visual starting point, not a completed client installation or a supplied construction drawing.\n\n## What to Review for Your Space\n\nCompare the logo scale with the reception wall, the visible face finish and the halo behind the letters. Wall colour, texture, mounting distance and room lighting can change the result. Send a wider photograph and approximate wall measurements with your artwork.\n\n## Turn the Direction into Your Own Specification\n\nReview overall dimensions, individual shapes, face and side finish, light colour, fixing method, cable route and access. Any required documents and the local installer''s responsibilities must be agreed before the design is approved for production.","image":"/assets/office-halo.webp","imageAlt":"Office Logo Sign illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept","product":"backlit-letters","setting":"Office","indexable":false,"sort":0,"gallery":[{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Individual illuminated letters from the supplier brochure","caption":"Supplier reference — individual letter samples with rear illumination."}]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('project-storefront-concept','project','storefront-concept','{"title":"Storefront Sign","intro":"Illuminated lettering on a commercial facade.","body":"## The Design Brief\n\nThis illustrative concept explores illuminated lettering on a commercial facade. No customer, location or completed delivery is claimed. It helps describe the visibility and character you want for your own business frontage.\n\n## What to Review for Your Facade\n\nConsider the sign area, viewing distance, existing surface, surrounding light and access for installation. Send your own logo, a straight-on location photo and approximate measurements. Any property or local approval requirements need to be identified by the parties responsible for the site.\n\n## Confirm the Construction Separately\n\nDiscuss the proposed face, returns, depth, finish, lighting and mounting rather than assuming the illustration defines them. Destination requirements, supplied components, shipping and local installation responsibilities are part of the project review.","image":"/assets/storefront-wide.webp","imageAlt":"Storefront Sign illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept","product":"led-channel-letters","setting":"Storefront","indexable":false,"sort":0,"gallery":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Unlit letter face and metal return from the supplier brochure","caption":"Supplier reference — unlit face and return reference."}]}','{"title":"Storefront Sign","intro":"Illuminated lettering on a commercial facade.","body":"## The Design Brief\n\nThis illustrative concept explores illuminated lettering on a commercial facade. No customer, location or completed delivery is claimed. It helps describe the visibility and character you want for your own business frontage.\n\n## What to Review for Your Facade\n\nConsider the sign area, viewing distance, existing surface, surrounding light and access for installation. Send your own logo, a straight-on location photo and approximate measurements. Any property or local approval requirements need to be identified by the parties responsible for the site.\n\n## Confirm the Construction Separately\n\nDiscuss the proposed face, returns, depth, finish, lighting and mounting rather than assuming the illustration defines them. Destination requirements, supplied components, shipping and local installation responsibilities are part of the project review.","image":"/assets/storefront-wide.webp","imageAlt":"Storefront Sign illustrative concept","imageKind":"concept","sourceNote":"ImageGen concept","product":"led-channel-letters","setting":"Storefront","indexable":false,"sort":0,"gallery":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Unlit letter face and metal return from the supplier brochure","caption":"Supplier reference — unlit face and return reference."}]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('page-for-sign-companies','page','for-sign-companies','{"title":"Custom Sign Fabrication for Sign Companies & Installers","intro":"Sourcing custom lettering or illuminated signs for a customer project? We coordinate with manufacturing partners to review your specifications and prepare a project-based supply quote.","body":"## Fabrication Support for Your Customer Projects\n\nThis enquiry route is for sign companies, installers, fit-out contractors and procurement teams reviewing a custom sign supply requirement. Start with the specification you have; open technical questions can be clarified before a production-ready scope is approved.\n\n## Prepare the Brief in Four Parts\n\n### Artwork and Dimensions\n\nShare vector artwork or drawings where available, overall and individual letter sizes, quantities and any tolerances that your project requires. Identify provisional measurements and the person responsible for final approval.\n\n### Materials, Finishes and Lighting\n\nSpecify the material or visual reference, face and side appearance, illuminated or unlit effect, and any colour approval requirement. Identify destination-specific electrical requirements and supporting documents at the enquiry stage.\n\n### Mounting and Site Coordination\n\nTell us the mounting surface, proposed fixing method, cable access and the local installation team''s requirements. Agree which drawings, fixing parts or layout aids are included and which site work remains with the local contractor.\n\n### Packing and Delivery\n\nConfirm the number of signs, destination, handling requirements, labelling and whether items need to be grouped by installation location. Shipping scope, import responsibilities and timing must be agreed in the quotation.\n\n## Agree the Review and Approval Points\n\nDiscuss drawing review, finish or lighting samples where needed, production approval and the checks or records required before dispatch. These are project arrangements to confirm, not services automatically included with every enquiry.\n\n## Repeat or Multi-site Requirements\n\nIf consistency across several signs matters, identify the approved master reference, quantities by location and which dimensions or details may vary. Repeat supply, schedule, packaging and commercial terms are reviewed for the actual requirement; no standing capacity commitment is implied.\n\n## Production References\n\nThe supplier photographs below illustrate equipment and fabrication activity. They do not establish a verified tolerance, certification or production rate. Ask about the actual construction and evidence needed for your project.\n\n## Questions for Trade Buyers\n\n### Can I start with a preliminary drawing?\n\nYes. Mark undecided dimensions or details so they can be reviewed before quotation assumptions become production instructions.\n\n### Do you provide local installation?\n\nDo not assume it is included. Agree fabrication, supplied parts, documentation, shipping, site access and local installation responsibilities separately.\n\n### Are certificates or inspection records included?\n\nState your requirements before quoting. Document availability and applicability must be checked for the actual product, destination and scope.","image":"/assets/craft-details.webp","imageAlt":"Illustrative sign inspection","imageKind":"concept","sort":0,"indexable":true,"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-cutting-bed.webp","alt":"Cutting bed shown in the supplier brochure","caption":"Supplier reference — equipment reference; no throughput or accuracy claim."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','{"title":"Custom Sign Fabrication for Sign Companies & Installers","intro":"Sourcing custom lettering or illuminated signs for a customer project? We coordinate with manufacturing partners to review your specifications and prepare a project-based supply quote.","body":"## Fabrication Support for Your Customer Projects\n\nThis enquiry route is for sign companies, installers, fit-out contractors and procurement teams reviewing a custom sign supply requirement. Start with the specification you have; open technical questions can be clarified before a production-ready scope is approved.\n\n## Prepare the Brief in Four Parts\n\n### Artwork and Dimensions\n\nShare vector artwork or drawings where available, overall and individual letter sizes, quantities and any tolerances that your project requires. Identify provisional measurements and the person responsible for final approval.\n\n### Materials, Finishes and Lighting\n\nSpecify the material or visual reference, face and side appearance, illuminated or unlit effect, and any colour approval requirement. Identify destination-specific electrical requirements and supporting documents at the enquiry stage.\n\n### Mounting and Site Coordination\n\nTell us the mounting surface, proposed fixing method, cable access and the local installation team''s requirements. Agree which drawings, fixing parts or layout aids are included and which site work remains with the local contractor.\n\n### Packing and Delivery\n\nConfirm the number of signs, destination, handling requirements, labelling and whether items need to be grouped by installation location. Shipping scope, import responsibilities and timing must be agreed in the quotation.\n\n## Agree the Review and Approval Points\n\nDiscuss drawing review, finish or lighting samples where needed, production approval and the checks or records required before dispatch. These are project arrangements to confirm, not services automatically included with every enquiry.\n\n## Repeat or Multi-site Requirements\n\nIf consistency across several signs matters, identify the approved master reference, quantities by location and which dimensions or details may vary. Repeat supply, schedule, packaging and commercial terms are reviewed for the actual requirement; no standing capacity commitment is implied.\n\n## Production References\n\nThe supplier photographs below illustrate equipment and fabrication activity. They do not establish a verified tolerance, certification or production rate. Ask about the actual construction and evidence needed for your project.\n\n## Questions for Trade Buyers\n\n### Can I start with a preliminary drawing?\n\nYes. Mark undecided dimensions or details so they can be reviewed before quotation assumptions become production instructions.\n\n### Do you provide local installation?\n\nDo not assume it is included. Agree fabrication, supplied parts, documentation, shipping, site access and local installation responsibilities separately.\n\n### Are certificates or inspection records included?\n\nState your requirements before quoting. Document availability and applicability must be checked for the actual product, destination and scope.","image":"/assets/craft-details.webp","imageAlt":"Illustrative sign inspection","imageKind":"concept","sort":0,"indexable":true,"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-cutting-bed.webp","alt":"Cutting bed shown in the supplier brochure","caption":"Supplier reference — equipment reference; no throughput or accuracy claim."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('page-how-it-works','page','how-it-works','{"title":"How Your Custom Sign Project Works","intro":"Start with what you know. We’ll clarify the remaining details with you before confirming a quote and production specification.","body":"## 1. Share the Starting Point\n\nTell us the use, delivery country and preferred sign style. A logo, reference photo or initial idea is enough to begin. If dimensions, material or timing are undecided, say so rather than guessing a production specification.\n\n## 2. Review the Design and Location\n\nContinue the discussion with artwork, approximate dimensions, quantities and photos of the intended mounting area. We clarify the face, finish, depth, lighting and fixing direction, together with destination-specific requirements that need review.\n\n## 3. Check the Project Quote\n\nRead the proposed specifications, currency, included components, delivery scope, costs and exclusions. If information is provisional, ask which assumptions the quote uses and what could change when the details are confirmed. An enquiry or preliminary quote is not production approval.\n\n## 4. Confirm the Order and Production Requirements\n\nConfirm artwork, spelling, dimensions, finishes, lighting, quantities and approval responsibilities in writing. The quotation and order documents establish the seller, payment arrangements, applicable terms and the point at which fabrication is authorised.\n\n## 5. Fabrication, Checks and Packing\n\nThe production partner works to the approved requirements. Agree in advance which appearance checks, lighting checks, inspection records, packing arrangements and dispatch information are needed. Supplier photographs are references, not proof that a particular order has passed inspection.\n\n## 6. Shipping and Installation Preparation\n\nConfirm the destination, shipping scope, production and transit timing, import responsibilities and the information required by the local installer. Identify any fixing, electrical connection, access or approval work outside the supplied scope before dispatch.\n\n## Useful to Have, but Not Required to Start\n\n- Your logo, text or reference image.\n- Approximate dimensions and quantity.\n- A photo of the intended location and mounting surface.\n- Indoor or outdoor use.\n- Delivery country and city.\n- Preferred timing and any opening or installation deadline.\n\n## Questions About the Process\n\n### When is the price confirmed?\n\nAfter the project information and scope have been reviewed. Confirm any assumptions, exclusions and validity conditions in the quotation before agreeing the order.\n\n### Can I change the design after approval?\n\nContact your project representative promptly. Whether a change is possible, and any cost or timing impact, depends on the actual stage and agreed order terms. Do not assume a requested change has been accepted until confirmed.\n\n### What if something arrives damaged or appears incorrect?\n\nKeep the packaging, photograph the issue and contact the agreed project contact promptly with the order reference. The relevant order documents and support arrangements determine the next steps.","image":"","imageAlt":"Illustrative sign inspection","imageKind":"concept","sort":0,"indexable":true,"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','{"title":"How Your Custom Sign Project Works","intro":"Start with what you know. We’ll clarify the remaining details with you before confirming a quote and production specification.","body":"## 1. Share the Starting Point\n\nTell us the use, delivery country and preferred sign style. A logo, reference photo or initial idea is enough to begin. If dimensions, material or timing are undecided, say so rather than guessing a production specification.\n\n## 2. Review the Design and Location\n\nContinue the discussion with artwork, approximate dimensions, quantities and photos of the intended mounting area. We clarify the face, finish, depth, lighting and fixing direction, together with destination-specific requirements that need review.\n\n## 3. Check the Project Quote\n\nRead the proposed specifications, currency, included components, delivery scope, costs and exclusions. If information is provisional, ask which assumptions the quote uses and what could change when the details are confirmed. An enquiry or preliminary quote is not production approval.\n\n## 4. Confirm the Order and Production Requirements\n\nConfirm artwork, spelling, dimensions, finishes, lighting, quantities and approval responsibilities in writing. The quotation and order documents establish the seller, payment arrangements, applicable terms and the point at which fabrication is authorised.\n\n## 5. Fabrication, Checks and Packing\n\nThe production partner works to the approved requirements. Agree in advance which appearance checks, lighting checks, inspection records, packing arrangements and dispatch information are needed. Supplier photographs are references, not proof that a particular order has passed inspection.\n\n## 6. Shipping and Installation Preparation\n\nConfirm the destination, shipping scope, production and transit timing, import responsibilities and the information required by the local installer. Identify any fixing, electrical connection, access or approval work outside the supplied scope before dispatch.\n\n## Useful to Have, but Not Required to Start\n\n- Your logo, text or reference image.\n- Approximate dimensions and quantity.\n- A photo of the intended location and mounting surface.\n- Indoor or outdoor use.\n- Delivery country and city.\n- Preferred timing and any opening or installation deadline.\n\n## Questions About the Process\n\n### When is the price confirmed?\n\nAfter the project information and scope have been reviewed. Confirm any assumptions, exclusions and validity conditions in the quotation before agreeing the order.\n\n### Can I change the design after approval?\n\nContact your project representative promptly. Whether a change is possible, and any cost or timing impact, depends on the actual stage and agreed order terms. Do not assume a requested change has been accepted until confirmed.\n\n### What if something arrives damaged or appears incorrect?\n\nKeep the packaging, photograph the issue and contact the agreed project contact promptly with the order reference. The relevant order documents and support arrangements determine the next steps.","image":"","imageAlt":"Illustrative sign inspection","imageKind":"concept","sort":0,"indexable":true,"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('page-about','page','about','{"title":"Custom Signs, Through Clear Project Coordination","intro":"Custom Sign Forge works with manufacturing partners to supply custom business signs, illuminated lettering and dimensional signs for overseas projects.","body":"## Custom Signs Through Project Coordination\n\nCustom Sign Forge helps overseas business owners, sign companies and installers discuss custom lettering and signage with manufacturing partners. Our role is to coordinate the enquiry, clarify open requirements and bring the agreed supply scope into the quotation and order documents.\n\n## Our Role and the Manufacturing Partner''s Role\n\nWe handle project communication and coordinate the proposed construction, finish, lighting and delivery requirements with production partners. We do not present a partner''s premises or equipment as our own factory. The seller, supplied items and responsibilities for a particular order are identified in its quotation and order documents.\n\n## From a Reference to an Agreed Specification\n\nYou can start with a logo, photograph or initial idea. We review dimensions, materials, lighting, quantities, destination and installation requirements before the project is treated as ready for production. Approval points and any remaining assumptions should be clear in writing.\n\n## What the Images Show\n\nThe photographs below come from supplier promotional material supplied for this project. They show production references, not a claim about ownership, capacity, certification or a completed Custom Sign Forge customer order. Generated concepts elsewhere on the site are labelled separately.\n\n## Checks, Packing and Delivery\n\nAny agreed appearance checks, lighting review, inspection records, packaging and shipment documents need to be included in the project scope. Availability, responsibility and cost are confirmed per order; we do not publish unverified production volumes, universal delivery times or installation coverage.\n\n## Tell Us About Your Project\n\nShare the sign style, intended use, delivery country and anything you already know about the design. You do not need a final drawing or budget to start. Use the enquiry page to save the initial details and obtain a reference.","image":"/assets/craft-details.webp","imageAlt":"Illustrative sign inspection","imageKind":"concept","sort":0,"indexable":true,"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','{"title":"Custom Signs, Through Clear Project Coordination","intro":"Custom Sign Forge works with manufacturing partners to supply custom business signs, illuminated lettering and dimensional signs for overseas projects.","body":"## Custom Signs Through Project Coordination\n\nCustom Sign Forge helps overseas business owners, sign companies and installers discuss custom lettering and signage with manufacturing partners. Our role is to coordinate the enquiry, clarify open requirements and bring the agreed supply scope into the quotation and order documents.\n\n## Our Role and the Manufacturing Partner''s Role\n\nWe handle project communication and coordinate the proposed construction, finish, lighting and delivery requirements with production partners. We do not present a partner''s premises or equipment as our own factory. The seller, supplied items and responsibilities for a particular order are identified in its quotation and order documents.\n\n## From a Reference to an Agreed Specification\n\nYou can start with a logo, photograph or initial idea. We review dimensions, materials, lighting, quantities, destination and installation requirements before the project is treated as ready for production. Approval points and any remaining assumptions should be clear in writing.\n\n## What the Images Show\n\nThe photographs below come from supplier promotional material supplied for this project. They show production references, not a claim about ownership, capacity, certification or a completed Custom Sign Forge customer order. Generated concepts elsewhere on the site are labelled separately.\n\n## Checks, Packing and Delivery\n\nAny agreed appearance checks, lighting review, inspection records, packaging and shipment documents need to be included in the project scope. Availability, responsibility and cost are confirmed per order; we do not publish unverified production volumes, universal delivery times or installation coverage.\n\n## Tell Us About Your Project\n\nShare the sign style, intended use, delivery country and anything you already know about the design. You do not need a final drawing or budget to start. Use the enquiry page to save the initial details and obtain a reference.","image":"/assets/craft-details.webp","imageAlt":"Illustrative sign inspection","imageKind":"concept","sort":0,"indexable":true,"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('landing-custom-logo-signs','landing','custom-logo-signs','{"title":"Turn Your Business Logo into a Custom Sign","intro":"**H1**：Turn Your Business Logo into a Custom Sign","body":"## Choose the Effect Before the Fine Detail\n\nExplore front-lit lettering, a halo behind your logo or an unlit dimensional finish. A reference helps explain the appearance you want; the materials, lighting and mounting arrangement are reviewed for your own location.\n\n## Bring Your Logo and the Space Together\n\nSend your artwork or a clear reference, an approximate size and a photo of the wall or fascia. Tell us whether the sign is indoors or outdoors, the delivery country and any preferred timing. Missing details can be discussed before you approve a specification.\n\n## What Happens After Your Enquiry?\n\nWe review the design direction and open requirements with the manufacturing partner, then prepare a project-based quote. Confirm the artwork, dimensions, finish, lighting, supplied items, shipping and installation responsibilities before production is authorised.\n\n## Questions from Business Owners\n\n### Do I need a finished design?\n\nNo. A logo, text or example can start the conversation. Production artwork and final measurements must be confirmed later.\n\n### Is there a fixed price for the pictured sign?\n\nNo. The examples show a visual direction. Your size, construction, finish, lighting, quantity and delivery scope determine the quote.\n\n### Is installation included?\n\nDo not assume it is. Tell us about your location and local installer so supplied fixing parts, documents and site work can be agreed.","image":"/assets/office-halo.webp","imageAlt":"Custom signage concept","imageKind":"concept","indexable":false,"sort":0,"relatedProducts":["led-channel-letters","backlit-letters","acrylic-letters"],"relatedProjects":["office-logo-concept","storefront-concept"]}','{"title":"Turn Your Business Logo into a Custom Sign","intro":"**H1**：Turn Your Business Logo into a Custom Sign","body":"## Choose the Effect Before the Fine Detail\n\nExplore front-lit lettering, a halo behind your logo or an unlit dimensional finish. A reference helps explain the appearance you want; the materials, lighting and mounting arrangement are reviewed for your own location.\n\n## Bring Your Logo and the Space Together\n\nSend your artwork or a clear reference, an approximate size and a photo of the wall or fascia. Tell us whether the sign is indoors or outdoors, the delivery country and any preferred timing. Missing details can be discussed before you approve a specification.\n\n## What Happens After Your Enquiry?\n\nWe review the design direction and open requirements with the manufacturing partner, then prepare a project-based quote. Confirm the artwork, dimensions, finish, lighting, supplied items, shipping and installation responsibilities before production is authorised.\n\n## Questions from Business Owners\n\n### Do I need a finished design?\n\nNo. A logo, text or example can start the conversation. Production artwork and final measurements must be confirmed later.\n\n### Is there a fixed price for the pictured sign?\n\nNo. The examples show a visual direction. Your size, construction, finish, lighting, quantity and delivery scope determine the quote.\n\n### Is installation included?\n\nDo not assume it is. Tell us about your location and local installer so supplied fixing parts, documents and site work can be agreed.","image":"/assets/office-halo.webp","imageAlt":"Custom signage concept","imageKind":"concept","indexable":false,"sort":0,"relatedProducts":["led-channel-letters","backlit-letters","acrylic-letters"],"relatedProjects":["office-logo-concept","storefront-concept"]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('landing-sign-fabrication','landing','sign-fabrication','{"title":"Custom Lettering & Sign Fabrication for Your Next Project","intro":"Working on a customer sign project? Share your drawings or sourcing requirements for a project-based fabrication and supply quote.","body":"## A Clear Brief for a Fabrication Quote\n\nShare drawings, artwork, quantities and destination details for your customer project. Mark any measurements, materials, finish or lighting requirements that still need review rather than treating a reference photograph as a final specification.\n\n## Agree the Supply Scope\n\nDiscuss letter construction, mounting and cable access, included components, review drawings, finish or lighting approval and any required inspection records. State destination-specific documentation needs early so applicability can be checked before quoting.\n\n## Coordinate Packing and Local Installation\n\nIdentify grouping or labelling by location, packing requirements, shipping arrangements and the local installer''s responsibilities. Do not assume site measurements, access equipment, electrical connection or local approvals are part of the supply quote.\n\n## Repeat Requirements\n\nFor several signs or locations, send the master reference and variations together. We review consistency, quantities and schedule with the production partner for the actual order.\n\n## Questions from Trade Buyers\n\n### Can you quote while some dimensions are provisional?\n\nAn initial review can start, but any assumptions and required final approvals must be clear in the proposal.\n\n### Can you supply the paperwork my project needs?\n\nList the required drawings, records or compliance evidence at the start. Availability and relevance must be confirmed for the product and destination; a component document is not blanket approval of a finished sign.","image":"/assets/craft-details.webp","imageAlt":"Custom signage concept","imageKind":"concept","indexable":false,"sort":0,"relatedProducts":["metal-letters","led-channel-letters","specialty-signs"],"relatedProjects":["metal-letter-reference","exposed-light-reference"],"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','{"title":"Custom Lettering & Sign Fabrication for Your Next Project","intro":"Working on a customer sign project? Share your drawings or sourcing requirements for a project-based fabrication and supply quote.","body":"## A Clear Brief for a Fabrication Quote\n\nShare drawings, artwork, quantities and destination details for your customer project. Mark any measurements, materials, finish or lighting requirements that still need review rather than treating a reference photograph as a final specification.\n\n## Agree the Supply Scope\n\nDiscuss letter construction, mounting and cable access, included components, review drawings, finish or lighting approval and any required inspection records. State destination-specific documentation needs early so applicability can be checked before quoting.\n\n## Coordinate Packing and Local Installation\n\nIdentify grouping or labelling by location, packing requirements, shipping arrangements and the local installer''s responsibilities. Do not assume site measurements, access equipment, electrical connection or local approvals are part of the supply quote.\n\n## Repeat Requirements\n\nFor several signs or locations, send the master reference and variations together. We review consistency, quantities and schedule with the production partner for the actual order.\n\n## Questions from Trade Buyers\n\n### Can you quote while some dimensions are provisional?\n\nAn initial review can start, but any assumptions and required final approvals must be clear in the proposal.\n\n### Can you supply the paperwork my project needs?\n\nList the required drawings, records or compliance evidence at the start. Availability and relevance must be confirmed for the product and destination; a component document is not blanket approval of a finished sign.","image":"/assets/craft-details.webp","imageAlt":"Custom signage concept","imageKind":"concept","indexable":false,"sort":0,"relatedProducts":["metal-letters","led-channel-letters","specialty-signs"],"relatedProjects":["metal-letter-reference","exposed-light-reference"],"gallery":[{"src":"/assets/supplier/supplier-laser-cutting.webp","alt":"Sheet material being cut by a laser in the supplier brochure","caption":"Supplier reference — cutting equipment shown by our production partner."},{"src":"/assets/supplier/supplier-forming-equipment.webp","alt":"Letter forming equipment shown in the supplier brochure","caption":"Supplier reference — forming equipment reference, not a guarantee of a particular construction."}]}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('project-front-lit-letter-reference','project','front-lit-letter-reference','{"title":"Letter Face & Return Reference","intro":"Unlit face and metal return construction from supplier material.","body":"## What This Reference Shows\n\nUnlit face and metal return construction from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately.","image":"/assets/supplier/letter-face-reference.webp","imageAlt":"Unlit face and metal return construction from supplier material.","imageKind":"supplier_reference","sourceNote":"User-authorised supplier brochure photograph; see docs/supplier-assets.json. Not a delivered client project.","indexable":false,"sort":10,"product":"led-channel-letters","setting":"Other","gallery":[]}','{"title":"Letter Face & Return Reference","intro":"Unlit face and metal return construction from supplier material.","body":"## What This Reference Shows\n\nUnlit face and metal return construction from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately.","image":"/assets/supplier/letter-face-reference.webp","imageAlt":"Unlit face and metal return construction from supplier material.","imageKind":"supplier_reference","sourceNote":"User-authorised supplier brochure photograph; see docs/supplier-assets.json. Not a delivered client project.","indexable":false,"sort":10,"product":"led-channel-letters","setting":"Other","gallery":[]}','published',10);
